/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    const {
        route
    } = event.payload.item;
    return {
        event: 'Adoption Blueprint Breadcrumbs',
        value: {
            businessObjectiveName: api.state.buisnessObjectiveName,
            applicationName: api.state.applicationName,
            navigatingTo: route,
            page: 'app-details'
        }
    };
}

